-- Datos iniciales sacados de los dossiers 2027 y 2028. Se puede re-ejecutar (upsert).

begin;

on conflict (fecha) do update set tarifa = excluded.tarifa, nivel_minimo = excluded.nivel_minimo;

on conflict (anio, nivel) do update set importe = excluded.importe;

on conflict (anio) do update set datos = excluded.datos, actualizado = now();

on conflict (fecha) do update set tarifa = excluded.tarifa, nivel_minimo = excluded.nivel_minimo;

on conflict (anio, nivel) do update set importe = excluded.importe;

on conflict (anio) do update set datos = excluded.datos, actualizado = now();

on conflict (id) do update set datos = excluded.datos, actualizado = now();

commit;
