insert into public.web_catalogo (id, datos) values (1, '{"menus": [{"id": "1", "nombre": "Menú 1", "tipo": "Menú tradicional", "aperitivo": "gala", "primero": "A", "segundo": "A", "resumen": "Aperitivo de Gala (24 referencias), primer plato, sorbete casero, segundo plato y postre."}, {"id": "2", "nombre": "Menú 2", "tipo": "Menú tradicional", "aperitivo": "gala", "primero": "B", "segundo": "B", "resumen": "Aperitivo de Gala (24 referencias), primer plato, sorbete casero, segundo plato y postre."}, {"id": "3", "nombre": "Menú 3", "tipo": "Menú tradicional", "aperitivo": "gala", "primero": "C", "segundo": "C", "resumen": "Aperitivo de Gala (24 referencias), primer plato de mar, sorbete casero, segundo plato premium y postre."}, {"id": "4", "nombre": "Menú 4", "tipo": "Aperitivo completo", "aperitivo": "gran", "primero": null, "segundo": "A", "resumen": "Gran Aperitivo Mas Llombart (42 referencias), sorbete casero, segundo plato y postre."}, {"id": "5", "nombre": "Menú 5", "tipo": "Aperitivo completo", "aperitivo": "gran", "primero": null, "segundo": "B", "resumen": "Gran Aperitivo Mas Llombart (42 referencias), sorbete casero, segundo plato y postre."}, {"id": "6", "nombre": "Menú 6", "tipo": "Aperitivo completo", "aperitivo": "gran", "primero": null, "segundo": "C", "resumen": "Gran Aperitivo Mas Llombart (42 referencias), sorbete casero, segundo plato premium y postre."}, {"id": "7", "nombre": "Menú 7", "tipo": "Solo aperitivo", "aperitivo": "gran", "primero": null, "segundo": null, "resumen": "Gran Aperitivo Mas Llombart (42 referencias) con buffets y shows incluidos: quesos, parrillada de carnes y marisco, showcooking de arroces, crepes y hot dogs en discoteca.", "incluye": ["Buffet de quesos con surtido de panes y vinos", "Parrillada de carnes, zamburiñas, almejas y navajas by Mas Llombart", "Showcooking de arroces by Mas Llombart", "Buffet de creps (discoteca)", "Carrito de hot dogs (discoteca)"]}, {"id": "8", "nombre": "Menú 8", "tipo": "Menú tradicional · Tari